// Package ratelimiter implements a token-bucket rate limiter.
package ratelimiter

import (
	"sync"
	"time"
)

// TokenBucket represents a token bucket rate limiter.
type TokenBucket struct {
	mu          sync.Mutex
	capacity    float64   // maximum number of tokens the bucket can hold
	tokens      float64   // current number of tokens in the bucket
	refillRate  float64   // tokens added per second
	lastRefill  time.Time // last time the bucket was refilled
}

// NewTokenBucket creates a new token bucket with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold
// refillRate: number of tokens added per second
func NewTokenBucket(capacity float64, refillRate float64) *TokenBucket {
	return &TokenBucket{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow checks if a request is permitted right now.
// It returns true if a token is available and consumes it, false otherwise.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	// Refill the bucket based on elapsed time
	tb.refill()

	// Check if there's a token available
	if tb.tokens >= 1.0 {
		tb.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on the elapsed time since last refill.
// This method must be called with the mutex held.
func (tb *TokenBucket) refill() {
	now := time.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	tb.lastRefill = now

	// Add tokens based on elapsed time, capped at capacity
	tb.tokens += elapsed * tb.refillRate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}
}

// Tokens returns the current number of tokens in the bucket (for debugging/testing).
func (tb *TokenBucket) Tokens() float64 {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	tb.refill()
	return tb.tokens
}
