// It is safe for concurrent use by multiple goroutines.
type TokenBucket struct {
	mu sync.Mutex

	capacity   float64 // maximum number of tokens the bucket can hold
	refillRate float64 // tokens added per second

	tokens     float64   // current number of tokens in the bucket
	lastRefill time.Time // last time tokens were refilled
}

// NewTokenBucket creates a new token bucket with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func NewTokenBucket(capacity, refillRate float64) *TokenBucket {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refillRate must be positive")
	}

	return &TokenBucket{
		capacity:   capacity,
		refillRate: refillRate,
		tokens:     capacity, // start full
		lastRefill: time.Now(),
	}
}

// Allow checks if a request is permitted right now.
// It consumes one token if available and returns true; otherwise returns false.
func (tb *TokenBucket) Allow() bool {
	tb.mu.Lock()
	defer tb.mu.Unlock()

	tb.refill()

	if tb.tokens >= 1.0 {
		tb.tokens--
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since last refill.
// Caller must hold the mutex.
func (tb *TokenBucket) refill() {
	now := time.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	if elapsed > 0 {
		tb.tokens += elapsed * tb.refillRate
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.lastRefill = now
	}
}

// Tokens returns the current number of tokens in the bucket (for debugging/testing).
func (tb *TokenBucket) Tokens() float64 {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	tb.refill()
	return tb.tokens
}
