package tokenbucket

import (
	"sync"
	"time"
)

// Limiter implements a token-bucket rate limiter.
// It is safe for concurrent use by multiple goroutines.
type Limiter struct {
	mu          sync.Mutex
	capacity    float64   // maximum number of tokens the bucket can hold
	tokens      float64   // current number of tokens in the bucket
	refillRate  float64   // tokens added per second
	lastRefill  time.Time // time of last refill
}

// New creates a new token-bucket limiter with the given capacity
// (maximum burst size) and refill rate (tokens per second).
// It panics if capacity <= 0 or refillRate <= 0.
func New(capacity, refillRate float64) *Limiter {
	if capacity <= 0 {
		panic("tokenbucket: capacity must be positive")
	}
	if refillRate <= 0 {
		panic("tokenbucket: refill rate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start full
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill()

	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since last refill.
// Caller must hold the mutex.
func (l *Limiter) refill() {
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now

	// Add tokens proportional to elapsed time, capped at capacity
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
}

// Tokens returns the current number of tokens available (for testing/debugging).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}
