package tokenbucket

import (
	"sync"
	"time"
)

// RateLimiter implements a token bucket rate limiter.
// It allows bursts up to the bucket capacity and refills at a fixed rate.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64
	tokens      float64
	refillRate  float64 // tokens per second
	lastRefill  time.Time
}

// NewRateLimiter creates a new token bucket rate limiter.
// capacity: maximum number of tokens the bucket can hold (burst size)
// refillRate: number of tokens added per second
func NewRateLimiter(capacity int, refillRate float64) *RateLimiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if refillRate <= 0 {
		panic("refill rate must be positive")
	}
	return &RateLimiter{
		capacity:   float64(capacity),
		tokens:     float64(capacity), // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()

	if rl.tokens >= 1.0 {
		rl.tokens--
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since last refill.
// Must be called with the mutex held.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	if elapsed > 0 {
		rl.tokens += elapsed * rl.refillRate
		if rl.tokens > rl.capacity {
			rl.tokens = rl.capacity
		}
		rl.lastRefill = now
	}
}

// Tokens returns the current number of tokens (for testing/debugging).
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}
