// Package tokenbucket implements a token-bucket rate limiter.
// The bucket is initialized full, and tokens are added at a fixed rate.
// Each Allow() call consumes one token if available.
package tokenbucket

import (
	"sync"
	"time"
)

// Limiter represents a token bucket rate limiter.
type Limiter struct {
	mu sync.Mutex

	capacity float64 // maximum number of tokens the bucket can hold
	tokens   float64 // current number of tokens in the bucket
	rate     float64 // tokens added per second

	lastRefill time.Time // last time tokens were refilled
}

// NewLimiter creates a new token bucket limiter with the given capacity
// (maximum burst size) and refill rate (tokens per second).
// The bucket starts completely full.
func NewLimiter(capacity, rate float64) *Limiter {
	now := time.Now()
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity,
		rate:       rate,
		lastRefill: now,
	}
}

// refill adds tokens based on elapsed time since last refill.
// Must be called with the mutex held.
func (l *Limiter) refill() {
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now

	// Add tokens proportional to elapsed time, capped at capacity
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available. The method is safe for
// concurrent use by multiple goroutines.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// First, refill the bucket based on elapsed time
	l.refill()

	// Check if we have at least one token
	if l.tokens >= 1.0 {
		l.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of tokens in the bucket.
// This is primarily useful for testing and debugging.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}
