// TestBurstAllowance verifies that the limiter allows up to capacity
// requests immediately when the bucket is full.
func TestBurstAllowance(t *testing.T) {
	capacity := 5.0
	rate := 1.0 // 1 token per second
	limiter := NewLimiter(capacity, rate)

	// First capacity requests should all be allowed
	for i := 0; i < int(capacity); i++ {
		if !limiter.Allow() {
			t.Fatalf("request %d should be allowed (burst)", i+1)
		}
	}

	// Next request should be denied (bucket is empty)
	if limiter.Allow() {
		t.Fatal("request beyond capacity should be denied")
	}
}

// TestRefillBehavior verifies that tokens are added over time.
