	capacity := 1.0
	rate := 2.0 // 2 tokens per second

	limiter := NewLimiter(capacity, rate)

	// Consume the initial token
	if !limiter.Allow() {
		t.Fatal("initial token should be available")
	}

	// Immediately after, no token should be available
	if limiter.Allow() {
		t.Fatal("token should not be available immediately after consumption")
