// RateLimiter implements a token-bucket algorithm for rate limiting.
// It allows a configurable burst capacity and refill rate.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64       // maximum number of tokens the bucket can hold
	tokens      float64       // current number of tokens in the bucket
	refillRate  float64       // tokens added per second
	lastRefill  time.Time     // last time tokens were refilled
}

// NewRateLimiter creates a new rate limiter with the given capacity
// and refill rate (tokens per second).
// capacity must be > 0 and refillRate must be >= 0.
func NewRateLimiter(capacity float64, refillRate float64) *RateLimiter {
	if capacity <= 0 {
		panic("capacity must be greater than 0")
	}
	if refillRate < 0 {
		panic("refillRate must be non-negative")
	}
	return &RateLimiter{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()

	if rl.tokens >= 1.0 {
		rl.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on elapsed time since last refill.
// Must be called with the mutex held.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()
	rl.lastRefill = now

	// Add tokens based on elapsed time, but don't exceed capacity
	rl.tokens += elapsed * rl.refillRate
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
}

// Tokens returns the current number of tokens in the bucket (for testing/debugging).
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.refill()
	return rl.tokens
}
