// Package ratelimiter implements a token-bucket rate limiter.
// It provides a thread-safe way to control the rate of operations
// using a configurable bucket capacity and refill rate.
package ratelimiter

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiting algorithm.
// Tokens are added to the bucket at a fixed rate, and each Allow()
// call consumes one token if available.
type RateLimiter struct {
	mu          sync.Mutex
	capacity    float64       // maximum number of tokens the bucket can hold
	tokens      float64       // current number of tokens in the bucket
	refillRate  float64       // tokens added per second
	lastRefill  time.Time     // last time tokens were refilled
}

// New creates a new RateLimiter with the specified capacity and refill rate.
//
// Parameters:
//   - capacity: maximum number of tokens the bucket can hold (must be > 0)
//   - refillRate: number of tokens added per second (must be > 0)
//
// Returns a pointer to the initialized RateLimiter.
func New(capacity float64, refillRate float64) *RateLimiter {
	if capacity <= 0 {
		capacity = 1
	}
	if refillRate <= 0 {
		refillRate = 1
	}

	return &RateLimiter{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		refillRate: refillRate,
		lastRefill: time.Now(),
	}
}

// Allow checks if a request is permitted right now.
// It returns true if a token is available (and consumes it),
// false otherwise.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	// Refill tokens based on elapsed time
	rl.refill()

	// Check if we have at least one token
	if rl.tokens >= 1 {
		rl.tokens--
		return true
	}

	return false
}

// refill adds tokens to the bucket based on the time elapsed
// since the last refill. This method must be called with the lock held.
func (rl *RateLimiter) refill() {
	now := time.Now()
	elapsed := now.Sub(rl.lastRefill).Seconds()

	// Add tokens based on elapsed time and refill rate
	rl.tokens += elapsed * rl.refillRate

	// Cap tokens at bucket capacity
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}

	rl.lastRefill = now
}

// Tokens returns the current number of tokens in the bucket.
// This is primarily for testing and monitoring purposes.
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	rl.refill()
	return rl.tokens
}

// Capacity returns the maximum capacity of the bucket.
func (rl *RateLimiter) Capacity() float64 {
	return rl.capacity
}

// RefillRate returns the configured refill rate (tokens per second).
func (rl *RateLimiter) RefillRate() float64 {
	return rl.refillRate
}
