// Package ratelimiter implements a token-bucket rate limiter.
package ratelimiter

import (
	"sync"
	"time"
)

// RateLimiter implements a token-bucket rate limiter.
// It allows a configurable number of tokens (capacity) to be
// accumulated, and refills at a configurable rate.
type RateLimiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	lastTime time.Time
}

// New creates a new RateLimiter with the given capacity and refill rate.
// capacity: maximum number of tokens the bucket can hold.
// rate: number of tokens added per second.
func New(capacity int, rate float64) *RateLimiter {
	if capacity <= 0 {
		panic("capacity must be positive")
	}
	if rate <= 0 {
		panic("rate must be positive")
	}
	return &RateLimiter{
		capacity: float64(capacity),
		rate:     rate,
		tokens:   float64(capacity), // start with a full bucket
		lastTime: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available, otherwise returns false.
func (rl *RateLimiter) Allow() bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	now := time.Now()
	// Calculate elapsed time since last refill
	elapsed := now.Sub(rl.lastTime).Seconds()
	// Refill tokens based on elapsed time
	rl.tokens += elapsed * rl.rate
	// Cap tokens at capacity
	if rl.tokens > rl.capacity {
		rl.tokens = rl.capacity
	}
	rl.lastTime = now

	// Check if a token is available
	if rl.tokens >= 1.0 {
		rl.tokens--
		return true
	}
	return false
}

// Tokens returns the current number of tokens in the bucket (for testing/debugging).
func (rl *RateLimiter) Tokens() float64 {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	return rl.tokens
}
