package ratelimit

import (
	"sync"
	"time"
)

// Limiter implements a token-bucket rate limiter.
// It allows a configurable burst capacity and refill rate.
// The zero value is not usable; use NewLimiter to create a limiter.
type Limiter struct {
	mu sync.Mutex

	capacity float64 // maximum number of tokens the bucket can hold
	tokens   float64 // current number of tokens in the bucket
	rate     float64 // tokens added per second

	lastRefill time.Time // last time tokens were refilled
}

// NewLimiter creates a new token-bucket limiter.
// capacity is the maximum number of tokens (burst size).
// rate is the number of tokens added per second (refill rate).
// Both capacity and rate must be positive.
func NewLimiter(capacity, rate float64) *Limiter {
	if capacity <= 0 || rate <= 0 {
		panic("ratelimit: capacity and rate must be positive")
	}
	return &Limiter{
		capacity:   capacity,
		tokens:     capacity, // start with a full bucket
		rate:       rate,
		lastRefill: time.Now(),
	}
}

// Allow reports whether a request is permitted right now.
// It consumes one token if available; otherwise returns false.
// The method is safe for concurrent use by multiple goroutines.
func (l *Limiter) Allow() bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill tokens based on elapsed time
	l.refill()

	// Check if we have at least one token
	if l.tokens >= 1 {
		l.tokens--
		return true
	}
	return false
}

// refill adds tokens to the bucket based on elapsed time since last refill.
// Caller must hold the mutex.
func (l *Limiter) refill() {
	now := time.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	l.lastRefill = now

	// Add tokens proportional to elapsed time, capped at capacity
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
}

// Tokens returns the current number of tokens in the bucket.
// This is primarily for testing and debugging.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	return l.tokens
}
